// ai-agents/harness/src/pr-body.ts: renders the PR body from the evidence pack with the pr-story headings (G8).
import type { Evidence } from "./evidence.js";  // plan, checks, QA results, receipt, links; loaded from .nova/ and S3
const lines = (items: Iterable<string>) => [...items].map((i) => `- ${i}`).join("\n") || "- None.";

export function render(ev: Evidence): string {
  const checks = ev.qaResults.map((c) => c.tableRow()).join("\n");  // "| QA-1: <user sees> | pass | <video link> |"
  return `### What changes
${ev.whatChanges}
### Why
${ev.jiraKey}: ${ev.ticketTitle}. Root cause: ${ev.rootCause} (\`${ev.rootCauseAt}\`)
### How it was checked
| Check | Result | Proof |
|---|---|---|
${checks}

Failing before the fix: ${ev.beforeRunLink} · passing after: ${ev.afterRunLink}

### What was not checked, and why
${lines(ev.checks.skipped.map(([name, why]) => `${name}: ${why}`))}
### Risk and rollback
Risk: ${ev.plan.risk} (${ev.plan.risk_reason}). Roll back by reverting this PR. Watch: ${ev.watch}
### Where to look first
${lines(ev.lookFirst.map(([path, why]) => `\`${path}\`: ${why}`))}
<details><summary>Self-review receipt, trace, harness suggestions, cost and time</summary>

${ev.receipt.line()}  <!-- "Found 6 · fixed 5 · left 1, because …" -->
Trace: ${ev.traceLink} · ${ev.minutes} min · $${ev.costUsd.toFixed(2)} (measured, not a limit)
${lines(ev.harnessSuggestions)}
</details>

### References
- [${ev.jiraKey}](https://rhino-fcp.atlassian.net/browse/${ev.jiraKey})

Requested-by: @${ev.requesterGithub}
`;
}

import type { GateEvidence } from "@rhinohealth/ai-agents-shared";  // qa_results, scope_judge, pr_judge, findings, reviewer_team
import { gh } from "../broker-client.js";  // every GitHub call goes through the broker, scoped to one repo

const DONE = new Set(["fixed", "answered", "with_a_person"]);

export interface GateResult {
  ready: boolean;
  blockers: string[];
}

export async function readyGate(pr: number, ev: GateEvidence): Promise<GateResult> {
  const checks = await gh<{ name: string; bucket: string }[]>(["pr", "checks", String(pr), "--required", "--json", "name,bucket"]);
  const blockers = checks.filter((c) => c.bucket !== "pass" && c.bucket !== "skipping")
    .map((c) => `CI: ${c.name} is ${c.bucket}`);
  blockers.push(...ev.qa_results.filter((q) => !q.passed).map((q) => `QA check ${q.id} failed`));
  if (ev.scope_judge.verdict === "veto" && !ev.scope_judge.explained) blockers.push("scope judge veto not resolved");
  if (!ev.pr_judge.ready) blockers.push("PR judge: the description has open items");
  const open = ev.findings.filter((f) => f.severity === "important" && !DONE.has(f.state));
  blockers.push(...open.map((f) => `open finding ${f.path}:${f.line}`));
  if (blockers.length) return { ready: false, blockers };  // stays a draft; nobody is pinged
  await gh(["pr", "ready", String(pr)]);
  await gh(["pr", "edit", String(pr), "--add-reviewer", ev.reviewer_team]);  // e.g. RhinoHealth/frontend-guild
  return { ready: true, blockers: [] };
}
// Then the workflow sets Nova state to "PR open", assigns the ticket back to the requester and posts in Slack.
